"""P8 review addendum (independent reviewer's F-S1, F-S3, F-C1, F-C3, F-C4, F-C6, F-C7). Does not replace any frozen report: it adds the quantities the review asked for.
unstratified cluster bootstrap for C1/C2, exact sign-flip enumeration, checkpoint-clustered WRI interval, sigma_run with interval and RMS pair difference,
no-valid-patch vs net-zero-edit counts, Meta-World checkpoints without a distinguishable difference."""
import itertools, json, sys
from pathlib import Path
import numpy as np, pandas as pd
ROOT = Path(__file__).resolve().parents[1]; sys.path.insert(0, str(ROOT))
from wsarena.analysis.metrics import load_runs
rng = np.random.default_rng(7); NB = 10000
man = {e["sha256"][:12]: e for e in json.loads((ROOT / "configs/tasks/ckpt_manifest.json").read_text())["entries"] if e["status"] == "built"}
def get(exp):
    d = load_runs(ROOT / "runs" / exp); d = d[d.status.isin(["verified", "failed"])].copy(); d["arm"] = d.run_id.str.split("__").str[2]; d["ckpt_id"] = d.ckpt.map(lambda c: man[c]["ckpt_id"]); d["level"] = d.ckpt_class.map({"S1": "L2", "S2": "L2", "S3": "L3"}); return d
def boot(x): x = np.asarray(x, float); b = [x[rng.integers(0, len(x), len(x))].mean() for _ in range(NB)]; return x.mean(), np.percentile(b, 2.5), np.percentile(b, 97.5)
def exact_p(x):
    x = np.asarray(x, float); n = len(x); obs = abs(x.mean()); c = 0
    for s in itertools.product((-1, 1), repeat=n): c += abs(np.dot(s, x) / n) >= obs - 1e-12
    return c / 2 ** n
base = pd.concat([get(e) for e in ("baselines-v1", "baselines-gain-v1", "baselines-mw-v1", "baselines-mwpeg-v1")]); base["arm"] = base.arm.replace({"random5": "random"})
out = ["# P8 review addendum (generated by scripts/analyze_review_fixes.py)", "", "Frozen reports are unchanged; these are the extra quantities the independent review asked for. Corrections are logged in PREREG §10.", ""]
out += ["## 1 C1/C2 with an UNSTRATIFIED cluster bootstrap and exact sign-flip p (L2 checkpoints)", "", "| tier | arm | contrast | n | mean diff | unstratified 95% CI | exact sign-flip p (raw) |", "|---|---|---|---|---|---|---|"]
for tier, exp, arms in (("Tier-0", "main-v1-t0", ["sonnet55-medium", "sonnet55-high", "opus55-medium", "opus55-high"]), ("Meta-World", "main-v1-mw", ["sonnet55-medium", "opus55-medium"])):
    d = get(exp); L2 = d[d.level == "L2"].groupby(["arm", "ckpt_id"]).d_sr_id.mean().unstack(0); ids = L2.index
    for a in arms:
        for ref in ("random", "analytic_ridge"):
            r = base[(base.arm == ref) & base.ckpt_id.isin(ids)].groupby("ckpt_id").d_sr_id.mean().reindex(ids); df = (L2[a] - r).dropna(); m, lo, hi = boot(df)
            out.append(f"| {tier} | {a} | vs {ref} | {len(df)} | {m:+.3f} | [{lo:+.3f}, {hi:+.3f}] | {exact_p(df):.4f} |")
# WRI clustered
t0, rep, bl = get("main-v1-t0"), get("main-v1-t0-rep"), get("main-v1-t0-blind"); bl["arm"] = bl.arm.str.replace("-blind", "")
full = pd.concat([t0[t0.arm.isin(["sonnet55-medium", "opus55-medium"])], rep]).groupby(["ckpt_id", "arm"]).d_sr_id.mean(); b = bl.groupby(["ckpt_id", "arm"]).d_sr_id.mean()
j = pd.concat([full.rename("f"), b.rename("b")], axis=1).dropna(); j["wri"] = j.f - j.b; per_ck = j.groupby("ckpt_id").wri.mean()
m, lo, hi = boot(j.wri); m2, lo2, hi2 = boot(per_ck)
out += ["", "## 2 Weight-reliance index (full minus blind)", "", f"- 16 checkpoint-model pairs treated as independent: {m:+.3f} [{lo:+.3f}, {hi:+.3f}] (as in the paper's first version)",
        f"- **checkpoint-clustered** (8 checkpoints, both models averaged): {m2:+.3f} [{lo2:+.3f}, {hi2:+.3f}]", f"- pairs with |WRI| <= 0.05: {(j.wri.abs() <= 0.05).sum()} of {len(j)}; with |WRI| >= 0.20: {(j.wri.abs() >= 0.20).sum()} of {len(j)}; scope: Tier-0, seed-2 checkpoints only, no Meta-World, no equivalence margin was pre-set"]
# sigma_run
def sig(m_, r_):
    x = pd.concat([m_[m_.arm.isin(["sonnet55-medium", "opus55-medium"])].set_index(["ckpt_id", "arm"]).d_sr_id.rename("a"), r_.set_index(["ckpt_id", "arm"]).d_sr_id.rename("b")], axis=1).dropna(); dd = (x.a - x.b).to_numpy()
    bs = [np.sqrt(np.mean(dd[rng.integers(0, len(dd), len(dd))] ** 2) / 2) for _ in range(NB)]; srt = np.sort(np.abs(dd))[:-2]
    return len(dd), np.sqrt(np.mean(dd ** 2) / 2), np.percentile(bs, 2.5), np.percentile(bs, 97.5), np.sqrt(np.mean(dd ** 2)), np.sqrt(np.mean(srt ** 2) / 2), (np.abs(dd) >= 0.10).mean()
out += ["", "## 3 Run-to-run spread (medium arms; sigma_run = SD of one run; RMS pair difference = sqrt(2) x sigma_run)", "", "| tier | pairs | sigma_run | 95% bootstrap CI | RMS pair difference | sigma_run without the 2 largest pairs | share of pairs differing >= 0.10 |", "|---|---|---|---|---|---|---|"]
for tier, a_, b_ in (("Tier-0", t0, rep), ("Meta-World", get("main-v1-mw"), get("main-v1-mw-rep"))):
    n, s, lo, hi, rms, s2, sh = sig(a_, b_); out.append(f"| {tier} | {n} | {s:.3f} | [{lo:.3f}, {hi:.3f}] | {rms:.3f} | {s2:.3f} | {sh:.0%} |")
# no valid patch vs net zero
rows = []
for tier, exp in (("Tier-0", "main-v1-t0"), ("Meta-World", "main-v1-mw")):
    for _, r in get(exp).iterrows():
        jj = json.loads(Path(r.path).read_text()); rows.append(dict(tier=tier, arm=r.arm, no_valid=jj["valid_patch_rounds"] == 0, net_zero=jj["identity"]["final_sha256"] == jj["identity"]["base_sha256"], h=r.d_sr_id))
R = pd.DataFrame(rows); out += ["", "## 4 'No real edit' split: no valid patch in any round vs final weights identical to the start", "", R.groupby(["tier", "arm"]).agg(runs=("no_valid", "size"), no_valid_patch=("no_valid", "sum"), final_equals_base=("net_zero", "sum")).to_markdown(), ""]
mw = get("main-v1-mw").groupby(["ckpt_id", "arm"]).d_sr_id.mean().unstack(); both_small = ((mw["opus55-medium"].abs() < 0.10) & (mw["sonnet55-medium"].abs() < 0.10)).sum()
out += [f"## 5 Meta-World: checkpoints where both editors have |gain| < 0.10: {both_small} of {len(mw)} ({both_small/len(mw):.0%}); the 0.10 band is about the size of sigma_run", ""]
fr = pd.concat([t0[t0.arm.isin(["sonnet55-medium", "opus55-medium"]) & t0.ckpt_id.str.endswith("seed2")], rep]).frac_changed.mean(); out += [f"## 6 Weights changed, matched set (medium arms, seed-2 checkpoints): full prompt {fr:.2f}; blind {bl.frac_changed.mean():.2f}", ""]
(ROOT / "reports/REVIEW_P8_ADDENDUM.md").write_text("\n".join(out)); print("\n".join(out))
